import re
import datetime
from config.settings import settings

def clean_model_output(text: str) -> str:
    """Strips away conversational preambles from LLM responses using config constraints."""
    if not text:
        return settings.DEFAULT_FALLBACK_STRING
    
    # Wipe away common conversational preambles generated by the LLM
    text = re.sub(r'^(the event is|the date is|the time is|the venue is|at|on)\s+', '', text, flags=re.IGNORECASE)
    
    # Match structural validation parameters against invalid indicator strings
    if text.lower() in ["none", "not mentioned", "unknown", "n/a", "", "no"]:
        return settings.DEFAULT_FALLBACK_STRING
        
    return text.strip()

def normalize_iso_datetime(iso_start_str: str) -> datetime.datetime:
    """Parses structural date tokens cleanly without local hardware clock dependencies."""
    try:
        # Standard parsing attempt targeting well-formed ISO timestamps
        return datetime.datetime.fromisoformat(iso_start_str)
    except (ValueError, TypeError):
        # Fallback system driven exclusively by business rules configured in settings
        now = datetime.datetime.now()
        fallback_date = now + datetime.timedelta(days=settings.DEFAULT_FALLBACK_DAYS_AHEAD)
        
        return datetime.datetime(
            year=fallback_date.year,
            month=fallback_date.month,
            day=fallback_date.day,
            hour=settings.DEFAULT_FALLBACK_HOUR,
            minute=settings.DEFAULT_FALLBACK_MINUTE,
            second=settings.DEFAULT_FALLBACK_SECOND
        )

def build_system_instruction() -> str:
    """Generates dynamic system instructions with current datetime context and few-shot examples."""
    current_time_context = datetime.datetime.now().strftime("%A, %B %d, %Y %I:%M %p")

    return (
        "You are a precise administrative assistant AI.\n"
        f"CURRENT TIME CONTEXT: {current_time_context}\n\n"
        "TASK: Extract event/deadline details from the email. Convert relative date expressions like '17th of this month', 'tomorrow', or 'this Friday' into strict ISO-8601 timestamps (YYYY-MM-DDTHH:MM:SS).\n\n"
        "EXAMPLE 1:\n"
        "Subject: Assignment Deadline\n"
        "Email Body: Please turn in your work by 23rd August at 11:59 PM.\n"
        "EVENT: Assignment Deadline\n"
        "ISO_START: 2026-08-23T23:59:00\n"
        "VENUE: Unknown\n\n"
        "EXAMPLE 2:\n"
        "Subject: Urgent Meeting: Semester Intern Report Submission\n"
        "Email Body: Submit your work by the 17th of this month.\n"
        "EVENT: Semester Intern Report Submission\n"
        "ISO_START: 2026-08-17T09:00:00\n"
        "VENUE: Unknown\n\n"
        "RULES:\n"
        "1. Output ONLY the 3 lines below with no intro text, markdown code blocks, or chat filler.\n"
        "2. If no explicit time is mentioned for a deadline, default time to 09:00:00.\n"
        "3. If the email contains no actionable date/event, set all values to 'Unknown'.\n\n"
        "REQUIRED OUTPUT FORMAT:\n"
        "EVENT: <Title>\n"
        "ISO_START: <YYYY-MM-DDTHH:MM:SS or Unknown>\n"
        "VENUE: <Location or Unknown>"
    )